head.script:
scwin.trigger2_onclick = function(e) {
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var url = "/sample/common_link/p_popup_modal_modaless_WPFF-286_(WSQ-3669)_sub2.xml";
	var options = {};
	options.id = "test";
	options.type = "litewindow";
	options.width = "300px";
	options.height = "400px";
	options.modal = "true";
	options.frameMode = "wframe";
	WebSquare.util.openPopup(url, options);
};
